def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pts.setdefault(grid[r][c], []).append((r, c))

    # Each diagonal pair defines a ray. The direction is away from the
    # compact multicolour seed pattern: in these examples the seed pattern
    # is at the end opposite the long extension.
    for color, p in pts.items():
        if len(p) < 2:
            continue
        for i in range(len(p)):
            for j in range(i + 1, len(p)):
                r1, c1 = p[i]
                r2, c2 = p[j]
                dr, dc = r2-r1, c2-c1
                if abs(dr) != 1 or abs(dc) != 1:
                    continue
                # Normally continue from the second point. If the pair lies
                # above a nearby non-background anchor, extend the other way.
                other = [(r, c) for col, q in pts.items() if col != color
                         for r, c in q]
                if other:
                    ar, ac = min(other, key=lambda x: abs(x[0]-(r1+r2)/2) +
                                 abs(x[1]-(c1+c2)/2))
                    if ar > (r1+r2)/2:
                        dr, dc = -dr, -dc
                        r, c = r1, c1
                    else:
                        r, c = r2, c2
                else:
                    r, c = r2, c2
                while 0 <= r+dr < h and 0 <= c+dc < w:
                    r, c = r+dr, c+dc
                    if out[r][c] == bg:
                        out[r][c] = color
                break
            else:
                continue
            break
    return out
